/* @lc app=leetcode id=1947 lang=kotlin */ class Solution { fun maxCompatibilitySum(students: Array<IntArray>, mentors: Array<IntArray>): Int = students.size.let { m -> Array(m) { i -> IntArray(m) { j -> students[i].zip(mentors[j]).count { it.first == it.second } } }.let { score -> IntArray(1 shl m).apply { (0 until (1 shl m)).forEach { mask -> (0 until m).forEach { j -> if ((mask and (1 shl j)) == 0) this[mask or (1 shl j)] = maxOf(this[mask or (1 shl j)], this[mask] + score[java.lang.Integer.bitCount(mask)][j]) } } }[(1 shl m) - 1] } } }